  logic reg_hr_d0_cfg_fixed_lat;
  logic w_hr_d0_cfg_fixed_lat_nxt;
  logic [4:0] reg_hr_d0_cfg_init_lat;
  logic [4:0] w_hr_d0_cfg_init_lat_nxt;
  logic [LPARA_DATA_W-1:0] w_hr_d0_cfg_value;
  logic w_we_hr_d0_trst;
  logic [15:0] reg_hr_d0_trst_t_rh;
  logic [15:0] w_hr_d0_trst_t_rh_nxt;
  logic [15:0] reg_hr_d0_trst_t_rp;
  logic [15:0] w_hr_d0_trst_t_rp_nxt;
  logic [LPARA_DATA_W-1:0] w_hr_d0_trst_value;
  logic w_we_hr_d0_trph;
  logic [15:0] reg_hr_d0_trph_t_rph;
  logic [15:0] w_hr_d0_trph_t_rph_nxt;
  logic [LPARA_DATA_W-1:0] w_hr_d0_trph_value;
  logic w_we_hr_d0_tvcs;
  logic [15:0] reg_hr_d0_tvcs_t_vcs;
  logic [15:0] w_hr_d0_tvcs_t_vcs_nxt;
  logic [LPARA_DATA_W-1:0] w_hr_d0_tvcs_value;
  logic w_we_hr_d0_tmin;
  logic [7:0] reg_hr_d0_tmin_t_css;
  logic [7:0] w_hr_d0_tmin_t_css_nxt;
  logic [7:0] reg_hr_d0_tmin_t_rwr;
  logic [7:0] w_hr_d0_tmin_t_rwr_nxt;
  logic [7:0] reg_hr_d0_tmin_t_cshi;
  logic [7:0] w_hr_d0_tmin_t_cshi_nxt;
  logic [LPARA_DATA_W-1:0] w_hr_d0_tmin_value;
  logic w_we_hr_d0_tcsm;
  logic [15:0] reg_hr_d0_tcsm_t_csm;
  logic [15:0] w_hr_d0_tcsm_t_csm_nxt;
  logic [LPARA_DATA_W-1:0] w_hr_d0_tcsm_value;
  logic w_we_hr_d0_rcap;
  logic [7:0] reg_hr_d0_rcap_tap;
  logic [7:0] w_hr_d0_rcap_tap_nxt;
  logic [LPARA_DATA_W-1:0] w_hr_d0_rcap_value;
  logic w_we_hr_d0_id;
  logic reg_hr_d0_id_id_chk_en;
  logic w_hr_d0_id_id_chk_en_nxt;
  logic [15:0] reg_hr_d0_id_id0_exp;
  logic [15:0] w_hr_d0_id_id0_exp_nxt;
  logic [LPARA_DATA_W-1:0] w_hr_d0_id_value;
  logic w_we_hr_d0_tmo;
  logic [15:0] reg_hr_d0_tmo_t_tmo;
  logic [15:0] w_hr_d0_tmo_t_tmo_nxt;
  logic [LPARA_DATA_W-1:0] w_hr_d0_tmo_value;
  logic [LPARA_DATA_W-1:0] w_hr_d0_idr_value;
  logic w_we_hr_d1_cfg;
  logic [2:0] reg_hr_d1_cfg_pasr;
  logic [2:0] w_hr_d1_cfg_pasr_nxt;
  logic [1:0] reg_hr_d1_cfg_blen;
  logic [1:0] w_hr_d1_cfg_blen_nxt;
  logic reg_hr_d1_cfg_hybrid;
  logic w_hr_d1_cfg_hybrid_nxt;
  logic [2:0] reg_hr_d1_cfg_drive;
  logic [2:0] w_hr_d1_cfg_drive_nxt;
  logic reg_hr_d1_cfg_fixed_lat;
  logic w_hr_d1_cfg_fixed_lat_nxt;
  logic [4:0] reg_hr_d1_cfg_init_lat;
  logic [4:0] w_hr_d1_cfg_init_lat_nxt;
  logic [LPARA_DATA_W-1:0] w_hr_d1_cfg_value;
  logic w_we_hr_d1_trst;
  logic [15:0] reg_hr_d1_trst_t_rh;
  logic [15:0] w_hr_d1_trst_t_rh_nxt;
  logic [15:0] reg_hr_d1_trst_t_rp;
  logic [15:0] w_hr_d1_trst_t_rp_nxt;
  logic [LPARA_DATA_W-1:0] w_hr_d1_trst_value;
  logic w_we_hr_d1_trph;
  logic [15:0] reg_hr_d1_trph_t_rph;
  logic [15:0] w_hr_d1_trph_t_rph_nxt;
  logic [LPARA_DATA_W-1:0] w_hr_d1_trph_value;
  logic w_we_hr_d1_tvcs;
  logic [15:0] reg_hr_d1_tvcs_t_vcs;
  logic [15:0] w_hr_d1_tvcs_t_vcs_nxt;
  logic [LPARA_DATA_W-1:0] w_hr_d1_tvcs_value;
  logic w_we_hr_d1_tmin;
  logic [7:0] reg_hr_d1_tmin_t_css;
  logic [7:0] w_hr_d1_tmin_t_css_nxt;
  logic [7:0] reg_hr_d1_tmin_t_rwr;
  logic [7:0] w_hr_d1_tmin_t_rwr_nxt;
  logic [7:0] reg_hr_d1_tmin_t_cshi;
  logic [7:0] w_hr_d1_tmin_t_cshi_nxt;
  logic [LPARA_DATA_W-1:0] w_hr_d1_tmin_value;
  logic w_we_hr_d1_tcsm;
  logic [15:0] reg_hr_d1_tcsm_t_csm;
  logic [15:0] w_hr_d1_tcsm_t_csm_nxt;
  logic [LPARA_DATA_W-1:0] w_hr_d1_tcsm_value;
  logic w_we_hr_d1_rcap;
  logic [7:0] reg_hr_d1_rcap_tap;
  logic [7:0] w_hr_d1_rcap_tap_nxt;
  logic [LPARA_DATA_W-1:0] w_hr_d1_rcap_value;
  logic w_we_hr_d1_id;
  logic reg_hr_d1_id_id_chk_en;
  logic w_hr_d1_id_id_chk_en_nxt;
  logic [15:0] reg_hr_d1_id_id0_exp;
  logic [15:0] w_hr_d1_id_id0_exp_nxt;
  logic [LPARA_DATA_W-1:0] w_hr_d1_id_value;
  logic w_we_hr_d1_tmo;
  logic [15:0] reg_hr_d1_tmo_t_tmo;
  logic [15:0] w_hr_d1_tmo_t_tmo_nxt;
  logic [LPARA_DATA_W-1:0] w_hr_d1_tmo_value;
  logic [LPARA_DATA_W-1:0] w_hr_d1_idr_value;

  // APB decode: the SETUP phase is PSEL high and PENABLE low and lasts one cycle per transfer.
  // A transfer is in error when the protection, the word alignment or the byte strobes fail
  // while i_slverr_en is 1.
  assign w_apb_setup    = i_apb_psel & ~i_apb_penable;
  assign w_apb_prot_ok  = i_protect_en ? ~i_apb_pprot[1] : 1'b1;
  assign w_apb_slverr   = i_slverr_en ? (~w_apb_prot_ok
                                         | (|i_apb_paddr[1:0])
                                         | (~&i_apb_pstrb & i_apb_pwrite)) : 1'b0;

  // Transfer without error, split into a write and a read.
  assign w_apb_complete = w_apb_setup & ~w_apb_slverr;
  assign w_apb_wr       = i_apb_pwrite & w_apb_complete;
  assign w_apb_rd       = ~i_apb_pwrite & w_apb_complete;

  // Address capture: holds the address of the last transfer without error.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_addr
    if (!i_rst_n_apb)
      reg_addr <= '0;
    else if (w_apb_complete)
      reg_addr <= i_apb_paddr;
  end

  // Write data capture: holds the data of the last write without error.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_wdata
    if (!i_rst_n_apb)
      reg_wdata <= '0;
    else if (w_apb_wr)
      reg_wdata <= i_apb_pwdata;
  end

  // Error response flop: loaded in every SETUP phase while i_slverr_en is 1, and held otherwise.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_slverr
    if (!i_rst_n_apb)
      reg_slverr <= 1'b0;
    else if (w_apb_setup & i_slverr_en)
      reg_slverr <= w_apb_slverr;
  end

  // PSLVERR output follows the error response flop.
  assign o_apb_pslverr = reg_slverr;

  // Register write enables: a write enable of the captured address.
  assign w_we_hr_ctrl = w_wr_en & (reg_addr == LPARA_HR_CTRL_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_clk = w_wr_en & (reg_addr == LPARA_HR_CLK_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_cmd = w_wr_en & (reg_addr == LPARA_HR_CMD_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_cmd_addr = w_wr_en & (reg_addr == LPARA_HR_CMD_ADDR_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_cmd_wdata = w_wr_en & (reg_addr == LPARA_HR_CMD_WDATA_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_cmd_rdata = w_wr_en & (reg_addr == LPARA_HR_CMD_RDATA_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_irq_raw = w_wr_en & (reg_addr == LPARA_HR_IRQ_RAW_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_irq_en = w_wr_en & (reg_addr == LPARA_HR_IRQ_EN_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_irq_inj = w_wr_en & (reg_addr == LPARA_HR_IRQ_INJ_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_tmo_log = w_wr_en & (reg_addr == LPARA_HR_TMO_LOG_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_d0_cfg = w_wr_en & (reg_addr == LPARA_HR_D0_CFG_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_d0_trst = w_wr_en & (reg_addr == LPARA_HR_D0_TRST_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_d0_trph = w_wr_en & (reg_addr == LPARA_HR_D0_TRPH_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_d0_tvcs = w_wr_en & (reg_addr == LPARA_HR_D0_TVCS_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_d0_tmin = w_wr_en & (reg_addr == LPARA_HR_D0_TMIN_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_d0_tcsm = w_wr_en & (reg_addr == LPARA_HR_D0_TCSM_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_d0_rcap = w_wr_en & (reg_addr == LPARA_HR_D0_RCAP_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_d0_id = w_wr_en & (reg_addr == LPARA_HR_D0_ID_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_d0_tmo = w_wr_en & (reg_addr == LPARA_HR_D0_TMO_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_d1_cfg = w_wr_en & (reg_addr == LPARA_HR_D1_CFG_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_d1_trst = w_wr_en & (reg_addr == LPARA_HR_D1_TRST_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_d1_trph = w_wr_en & (reg_addr == LPARA_HR_D1_TRPH_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_d1_tvcs = w_wr_en & (reg_addr == LPARA_HR_D1_TVCS_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_d1_tmin = w_wr_en & (reg_addr == LPARA_HR_D1_TMIN_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_d1_tcsm = w_wr_en & (reg_addr == LPARA_HR_D1_TCSM_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_d1_rcap = w_wr_en & (reg_addr == LPARA_HR_D1_RCAP_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_d1_id = w_wr_en & (reg_addr == LPARA_HR_D1_ID_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_hr_d1_tmo = w_wr_en & (reg_addr == LPARA_HR_D1_TMO_OFFSET[LPARA_ADDR_W-1:0]);

  // Read request and acknowledge toggles cross between the APB clock and the register clock.
  // Bus clock, read: the acknowledge is synchronized into the APB clock.
  m_csr_sync #(
    .PARA_LEVELS (LPARA_SYNC_STAGES)
  ) u_rd_ack_sync (
    .i_clk_dst   (i_clk_apb),
    .i_rst_n_dst (i_rst_n_apb),
    .i_d         (w_rd_ack),
    .o_q         (w_rd_ack_bus)
  );

  // Bus clock, read: the request is set by a read and cleared by the acknowledge.
  assign w_rd_req_nxt  = w_rd_ack_bus ? 1'b0 : (w_apb_rd ? 1'b1 : reg_rd_req);
  assign w_rd_ack_fall = reg_rd_ack_bus_dly & ~w_rd_ack_bus;

  // Bus clock, read: request flop and delayed acknowledge flop.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_rd_req
    if (!i_rst_n_apb) begin
      reg_rd_req         <= 1'b0;
      reg_rd_ack_bus_dly <= 1'b0;
    end else begin
      reg_rd_req         <= w_rd_req_nxt;
      reg_rd_ack_bus_dly <= w_rd_ack_bus;
    end
  end

  // Bus clock, write: the acknowledge is synchronized into the APB clock.
  m_csr_sync #(
    .PARA_LEVELS (LPARA_SYNC_STAGES)
  ) u_wr_ack_sync (
    .i_clk_dst   (i_clk_apb),
    .i_rst_n_dst (i_rst_n_apb),
    .i_d         (w_wr_ack),
    .o_q         (w_wr_ack_bus)
  );

  // Bus clock, write: the request is set by a write and cleared by the acknowledge.
  assign w_wr_req_nxt  = w_wr_ack_bus ? 1'b0 : (w_apb_wr ? 1'b1 : reg_wr_req);
  assign w_wr_ack_fall = reg_wr_ack_bus_dly & ~w_wr_ack_bus;

  // Bus clock, write: request flop and delayed acknowledge flop.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_wr_req
    if (!i_rst_n_apb) begin
      reg_wr_req         <= 1'b0;
      reg_wr_ack_bus_dly <= 1'b0;
    end else begin
      reg_wr_req         <= w_wr_req_nxt;
      reg_wr_ack_bus_dly <= w_wr_ack_bus;
    end
  end

  // Register clock, read: the request is synchronized into the register clock.
  m_csr_sync #(
    .PARA_LEVELS (LPARA_SYNC_STAGES)
  ) u_rd_req_sync (
    .i_clk_dst   (i_clk_reg),
    .i_rst_n_dst (i_rst_n_reg),
    .i_d         (reg_rd_req),
    .o_q         (w_rd_req_reg)
  );

  // Register clock, read: a new request is a rising edge; the acknowledge is the delayed request.
  always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_rd_req_reg
    if (!i_rst_n_reg)
      reg_rd_req_reg_dly <= 1'b0;
    else
      reg_rd_req_reg_dly <= w_rd_req_reg;
  end

  // Read enable: pulse on the rising edge of the request; the acknowledge is the delayed request.
  assign w_rd_en  = ~reg_rd_req_reg_dly & w_rd_req_reg;
  assign w_rd_ack = reg_rd_req_reg_dly;

  // Register clock, write: the request is synchronized into the register clock.
  m_csr_sync #(
    .PARA_LEVELS (LPARA_SYNC_STAGES)
  ) u_wr_req_sync (
    .i_clk_dst   (i_clk_reg),
    .i_rst_n_dst (i_rst_n_reg),
    .i_d         (reg_wr_req),
    .o_q         (w_wr_req_reg)
  );

  // Register clock, write: a new request is a rising edge; the acknowledge is the delayed request.
  always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_wr_req_reg
    if (!i_rst_n_reg)
      reg_wr_req_reg_dly <= 1'b0;
    else
      reg_wr_req_reg_dly <= w_wr_req_reg;
  end

  // Write enable: pulse on the rising edge of the request; the acknowledge is the delayed request.
  assign w_wr_en  = ~reg_wr_req_reg_dly & w_wr_req_reg;
  assign w_wr_ack = reg_wr_req_reg_dly;

  // PREADY: one pulse when a read or write is acknowledged, or after an error SETUP phase.
  assign w_pready_nxt = w_rd_ack_fall | w_wr_ack_fall | (w_apb_slverr & w_apb_setup);

  // PREADY flop: loaded with the next value, cleared by the reset.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_pready
    if (!i_rst_n_apb)
      reg_pready <= 1'b0;
    else
      reg_pready <= w_pready_nxt;
  end

  // PREADY output follows the PREADY flop.
  assign o_apb_pready = reg_pready;

  // hr_ctrl_resume next value (rwi): software write, then hardware write, then hold.
  assign w_hr_ctrl_resume_nxt = (w_we_hr_ctrl) ? reg_wdata[6]
                                 : (i_hw_we_hr_ctrl_resume) ? i_hw_wdata_hr_ctrl_resume
                                 : reg_hr_ctrl_resume;

  // hr_ctrl_tmo_act next value (rw): a software write loads it, otherwise hold.
  assign w_hr_ctrl_tmo_act_nxt = (w_we_hr_ctrl) ? reg_wdata[5] : reg_hr_ctrl_tmo_act;

  // hr_ctrl_merge_en next value (rw): a software write loads it, otherwise hold.
  assign w_hr_ctrl_merge_en_nxt = (w_we_hr_ctrl) ? reg_wdata[4] : reg_hr_ctrl_merge_en;

  // hr_ctrl_arb_mode next value (rw): a software write loads it, otherwise hold.
  assign w_hr_ctrl_arb_mode_nxt = (w_we_hr_ctrl) ? reg_wdata[3:2] : reg_hr_ctrl_arb_mode;

  // hr_ctrl_wr_posted next value (rw): a software write loads it, otherwise hold.
  assign w_hr_ctrl_wr_posted_nxt = (w_we_hr_ctrl) ? reg_wdata[1] : reg_hr_ctrl_wr_posted;

  // hr_ctrl_en next value (rw): a software write loads it, otherwise hold.
  assign w_hr_ctrl_en_nxt = (w_we_hr_ctrl) ? reg_wdata[0] : reg_hr_ctrl_en;

  // Register hr_ctrl: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_hr_ctrl
    if (!i_rst_n_reg) begin
      reg_hr_ctrl_resume <= 1'h0;
      reg_hr_ctrl_tmo_act <= 1'h0;
      reg_hr_ctrl_merge_en <= 1'h1;
      reg_hr_ctrl_arb_mode <= 2'h0;
      reg_hr_ctrl_wr_posted <= 1'h0;
      reg_hr_ctrl_en <= 1'h0;
    end else begin
      reg_hr_ctrl_resume <= w_hr_ctrl_resume_nxt;
      reg_hr_ctrl_tmo_act <= w_hr_ctrl_tmo_act_nxt;
      reg_hr_ctrl_merge_en <= w_hr_ctrl_merge_en_nxt;
      reg_hr_ctrl_arb_mode <= w_hr_ctrl_arb_mode_nxt;
      reg_hr_ctrl_wr_posted <= w_hr_ctrl_wr_posted_nxt;
      reg_hr_ctrl_en <= w_hr_ctrl_en_nxt;
    end
  end

  // Register hr_ctrl: output ports follow the flops.
  assign o_hr_ctrl_resume = reg_hr_ctrl_resume;
  assign o_hr_ctrl_tmo_act = reg_hr_ctrl_tmo_act;
  assign o_hr_ctrl_merge_en = reg_hr_ctrl_merge_en;
  assign o_hr_ctrl_arb_mode = reg_hr_ctrl_arb_mode;
  assign o_hr_ctrl_wr_posted = reg_hr_ctrl_wr_posted;
  assign o_hr_ctrl_en = reg_hr_ctrl_en;

  // Register hr_ctrl: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_hr_ctrl_value
    w_hr_ctrl_value = '0;
    w_hr_ctrl_value[6] = reg_hr_ctrl_resume;
    w_hr_ctrl_value[5] = reg_hr_ctrl_tmo_act;
    w_hr_ctrl_value[4] = reg_hr_ctrl_merge_en;
    w_hr_ctrl_value[3:2] = reg_hr_ctrl_arb_mode;
    w_hr_ctrl_value[1] = reg_hr_ctrl_wr_posted;
    w_hr_ctrl_value[0] = reg_hr_ctrl_en;
  end

  // Register hr_sts: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_hr_sts_value
    w_hr_sts_value = '0;
    w_hr_sts_value[14] = i_hr_sts_hold;
    w_hr_sts_value[13] = i_hr_sts_cmd_busy;
    w_hr_sts_value[12:10] = i_hr_sts_wr_out;
    w_hr_sts_value[9:7] = i_hr_sts_rd_out;
    w_hr_sts_value[6] = i_hr_sts_memrst_n;
    w_hr_sts_value[5] = i_hr_sts_pwr_good;
    w_hr_sts_value[3] = i_hr_sts_cfg_valid;
    w_hr_sts_value[2] = i_hr_sts_idle;
    w_hr_sts_value[1] = i_hr_sts_init_done;
    w_hr_sts_value[0] = i_hr_sts_init_busy;
  end

  // Register hr_cap: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_hr_cap_value
    w_hr_cap_value = '0;
    w_hr_cap_value[7:4] = i_hr_cap_dly_w;
    w_hr_cap_value[3:2] = i_hr_cap_num_cs;
    w_hr_cap_value[1] = i_hr_cap_mem_x16;
    w_hr_cap_value[0] = i_hr_cap_axi_w64;
  end

  // Register hr_size: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_hr_size_value
    w_hr_size_value = '0;
    w_hr_size_value[31:0] = i_hr_size_bytes;
  end

  // hr_clk_ck_phase next value (rw): a software write loads it, otherwise hold.
  assign w_hr_clk_ck_phase_nxt = (w_we_hr_clk) ? reg_wdata[9] : reg_hr_clk_ck_phase;

  // hr_clk_ck_diff next value (rw): a software write loads it, otherwise hold.
  assign w_hr_clk_ck_diff_nxt = (w_we_hr_clk) ? reg_wdata[8] : reg_hr_clk_ck_diff;

  // hr_clk_ck_div next value (rw): a software write loads it, otherwise hold.
