  end

  // hr_d1_trph_t_rph next value (rw): a software write loads it, otherwise hold.
  assign w_hr_d1_trph_t_rph_nxt = (w_we_hr_d1_trph) ? reg_wdata[15:0] : reg_hr_d1_trph_t_rph;

  // Register hr_d1_trph: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_hr_d1_trph
