  // Register hr_d1_trph: output ports follow the flops.
  assign o_hr_d1_trph_t_rph = reg_hr_d1_trph_t_rph;

  // Register hr_d1_trph: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_hr_d1_trph_value
