  assign w_hr_d1_tvcs_t_vcs_nxt = (w_we_hr_d1_tvcs) ? reg_wdata[15:0] : reg_hr_d1_tvcs_t_vcs;

  // Register hr_d1_tvcs: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_hr_d1_tvcs
