  end

  // Register hr_d1_tvcs: output ports follow the flops.
  assign o_hr_d1_tvcs_t_vcs = reg_hr_d1_tvcs_t_vcs;

  // Register hr_d1_tvcs: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_hr_d1_tvcs_value
