  // hr_d1_tmin_t_css next value (rw): a software write loads it, otherwise hold.
  assign w_hr_d1_tmin_t_css_nxt = (w_we_hr_d1_tmin) ? reg_wdata[23:16] : reg_hr_d1_tmin_t_css;

  // hr_d1_tmin_t_rwr next value (rw): a software write loads it, otherwise hold.
  assign w_hr_d1_tmin_t_rwr_nxt = (w_we_hr_d1_tmin) ? reg_wdata[15:8] : reg_hr_d1_tmin_t_rwr;

  // hr_d1_tmin_t_cshi next value (rw): a software write loads it, otherwise hold.
  assign w_hr_d1_tmin_t_cshi_nxt = (w_we_hr_d1_tmin) ? reg_wdata[7:0] : reg_hr_d1_tmin_t_cshi;

  // Register hr_d1_tmin: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_hr_d1_tmin
    if (!i_rst_n_reg) begin
      reg_hr_d1_tmin_t_css <= 8'h2;
      reg_hr_d1_tmin_t_rwr <= 8'h7;
      reg_hr_d1_tmin_t_cshi <= 8'h2;
    end else begin
      reg_hr_d1_tmin_t_css <= w_hr_d1_tmin_t_css_nxt;
      reg_hr_d1_tmin_t_rwr <= w_hr_d1_tmin_t_rwr_nxt;
      reg_hr_d1_tmin_t_cshi <= w_hr_d1_tmin_t_cshi_nxt;
    end
  end

  // Register hr_d1_tmin: output ports follow the flops.
  assign o_hr_d1_tmin_t_css = reg_hr_d1_tmin_t_css;
  assign o_hr_d1_tmin_t_rwr = reg_hr_d1_tmin_t_rwr;
  assign o_hr_d1_tmin_t_cshi = reg_hr_d1_tmin_t_cshi;

  // Register hr_d1_tmin: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_hr_d1_tmin_value
    w_hr_d1_tmin_value = '0;
    w_hr_d1_tmin_value[23:16] = reg_hr_d1_tmin_t_css;
    w_hr_d1_tmin_value[15:8] = reg_hr_d1_tmin_t_rwr;
    w_hr_d1_tmin_value[7:0] = reg_hr_d1_tmin_t_cshi;
  end

  // hr_d1_tcsm_t_csm next value (rw): a software write loads it, otherwise hold.
  assign w_hr_d1_tcsm_t_csm_nxt = (w_we_hr_d1_tcsm) ? reg_wdata[15:0] : reg_hr_d1_tcsm_t_csm;

  // Register hr_d1_tcsm: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_hr_d1_tcsm
    if (!i_rst_n_reg) begin
      reg_hr_d1_tcsm_t_csm <= 16'hA0;
    end else begin
      reg_hr_d1_tcsm_t_csm <= w_hr_d1_tcsm_t_csm_nxt;
    end
  end

  // Register hr_d1_tcsm: output ports follow the flops.
  assign o_hr_d1_tcsm_t_csm = reg_hr_d1_tcsm_t_csm;

  // Register hr_d1_tcsm: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_hr_d1_tcsm_value
    w_hr_d1_tcsm_value = '0;
    w_hr_d1_tcsm_value[15:0] = reg_hr_d1_tcsm_t_csm;
  end

  // hr_d1_rcap_tap next value (rw): a software write loads it, otherwise hold.
  assign w_hr_d1_rcap_tap_nxt = (w_we_hr_d1_rcap) ? reg_wdata[7:0] : reg_hr_d1_rcap_tap;

  // Register hr_d1_rcap: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_hr_d1_rcap
    if (!i_rst_n_reg) begin
      reg_hr_d1_rcap_tap <= 8'h0;
    end else begin
      reg_hr_d1_rcap_tap <= w_hr_d1_rcap_tap_nxt;
    end
  end

  // Register hr_d1_rcap: output ports follow the flops.
  assign o_hr_d1_rcap_tap = reg_hr_d1_rcap_tap;

  // Register hr_d1_rcap: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_hr_d1_rcap_value
    w_hr_d1_rcap_value = '0;
    w_hr_d1_rcap_value[7:0] = reg_hr_d1_rcap_tap;
  end

  // hr_d1_id_id_chk_en next value (rw): a software write loads it, otherwise hold.
  assign w_hr_d1_id_id_chk_en_nxt = (w_we_hr_d1_id) ? reg_wdata[16] : reg_hr_d1_id_id_chk_en;

  // hr_d1_id_id0_exp next value (rw): a software write loads it, otherwise hold.
  assign w_hr_d1_id_id0_exp_nxt = (w_we_hr_d1_id) ? reg_wdata[15:0] : reg_hr_d1_id_id0_exp;

  // Register hr_d1_id: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_hr_d1_id
    if (!i_rst_n_reg) begin
      reg_hr_d1_id_id_chk_en <= 1'h0;
      reg_hr_d1_id_id0_exp <= 16'h0;
    end else begin
      reg_hr_d1_id_id_chk_en <= w_hr_d1_id_id_chk_en_nxt;
      reg_hr_d1_id_id0_exp <= w_hr_d1_id_id0_exp_nxt;
    end
  end

  // Register hr_d1_id: output ports follow the flops.
  assign o_hr_d1_id_id_chk_en = reg_hr_d1_id_id_chk_en;
  assign o_hr_d1_id_id0_exp = reg_hr_d1_id_id0_exp;

  // Register hr_d1_id: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_hr_d1_id_value
    w_hr_d1_id_value = '0;
    w_hr_d1_id_value[16] = reg_hr_d1_id_id_chk_en;
    w_hr_d1_id_value[15:0] = reg_hr_d1_id_id0_exp;
  end

  // hr_d1_tmo_t_tmo next value (rw): a software write loads it, otherwise hold.
  assign w_hr_d1_tmo_t_tmo_nxt = (w_we_hr_d1_tmo) ? reg_wdata[15:0] : reg_hr_d1_tmo_t_tmo;

  // Register hr_d1_tmo: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_hr_d1_tmo
    if (!i_rst_n_reg) begin
      reg_hr_d1_tmo_t_tmo <= 16'h200;
    end else begin
      reg_hr_d1_tmo_t_tmo <= w_hr_d1_tmo_t_tmo_nxt;
    end
  end

  // Register hr_d1_tmo: output ports follow the flops.
  assign o_hr_d1_tmo_t_tmo = reg_hr_d1_tmo_t_tmo;

  // Register hr_d1_tmo: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_hr_d1_tmo_value
    w_hr_d1_tmo_value = '0;
    w_hr_d1_tmo_value[15:0] = reg_hr_d1_tmo_t_tmo;
  end

  // Register hr_d1_idr: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_hr_d1_idr_value
    w_hr_d1_idr_value = '0;
    w_hr_d1_idr_value[15:0] = i_hr_d1_idr_id0_act;
  end

  // Read data mux: value of the register at the captured address, 0 for any other address.
  always_comb begin : p_com_rdata
    w_rdata_nxt = '0;
    case (reg_addr)
      LPARA_HR_CTRL_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_ctrl_value;
      LPARA_HR_STS_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_sts_value;
      LPARA_HR_CAP_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_cap_value;
      LPARA_HR_SIZE_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_size_value;
      LPARA_HR_CLK_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_clk_value;
      LPARA_HR_CMD_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_cmd_value;
      LPARA_HR_CMD_ADDR_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_cmd_addr_value;
      LPARA_HR_CMD_WDATA_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_cmd_wdata_value;
      LPARA_HR_CMD_RDATA_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_cmd_rdata_value;
      LPARA_HR_IRQ_RAW_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_irq_raw_value;
      LPARA_HR_IRQ_EN_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_irq_en_value;
      LPARA_HR_IRQ_STS_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_irq_sts_value;
      LPARA_HR_IRQ_INJ_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_irq_inj_value;
      LPARA_HR_ERR_CNT_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_err_cnt_value;
      LPARA_HR_ERR_RA_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_err_ra_value;
      LPARA_HR_ERR_RI_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_err_ri_value;
      LPARA_HR_ERR_WA_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_err_wa_value;
      LPARA_HR_ERR_WI_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_err_wi_value;
      LPARA_HR_TMO_LOG_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_tmo_log_value;
      LPARA_HR_TMO_ADDR_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_tmo_addr_value;
      LPARA_HR_D0_CFG_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_d0_cfg_value;
      LPARA_HR_D0_TRST_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_d0_trst_value;
      LPARA_HR_D0_TRPH_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_d0_trph_value;
      LPARA_HR_D0_TVCS_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_d0_tvcs_value;
      LPARA_HR_D0_TMIN_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_d0_tmin_value;
      LPARA_HR_D0_TCSM_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_d0_tcsm_value;
      LPARA_HR_D0_RCAP_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_d0_rcap_value;
      LPARA_HR_D0_ID_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_d0_id_value;
      LPARA_HR_D0_TMO_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_d0_tmo_value;
      LPARA_HR_D0_IDR_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_d0_idr_value;
      LPARA_HR_D1_CFG_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_d1_cfg_value;
      LPARA_HR_D1_TRST_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_d1_trst_value;
      LPARA_HR_D1_TRPH_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_d1_trph_value;
      LPARA_HR_D1_TVCS_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_d1_tvcs_value;
      LPARA_HR_D1_TMIN_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_d1_tmin_value;
      LPARA_HR_D1_TCSM_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_d1_tcsm_value;
      LPARA_HR_D1_RCAP_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_d1_rcap_value;
      LPARA_HR_D1_ID_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_d1_id_value;
      LPARA_HR_D1_TMO_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_d1_tmo_value;
      LPARA_HR_D1_IDR_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_hr_d1_idr_value;
      default: w_rdata_nxt = '0;
    endcase
  end

  // Read data snapshot in the register clock domain, loaded by the read enable of that domain.
  always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_rdata
    if (!i_rst_n_reg)
      reg_rdata <= '0;
    else if (w_rd_en)
      reg_rdata <= w_rdata_nxt;
  end

  // Read data resynchronized to the APB clock: reg_rdata is stable when the acknowledge
  // pulse arrives, so that pulse samples it without a bit synchronizer.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_rdata_bus
    if (!i_rst_n_apb)
      reg_rdata_bus <= '0;
    else if (w_rd_ack_fall)
      reg_rdata_bus <= reg_rdata;
  end

  // PRDATA output follows the read data flop of the APB clock.
  assign o_apb_prdata = reg_rdata_bus;

endmodule
